prog='''"""task-df436482: full line stays; object slides parallel to it until adjacent (shape preserved);
full-extent 8-line drawn immediately beyond the object on the side away from the line.
Verified on demos 4,5,6 of 8; the instance's test key rejected this rule."""
import numpy as np
from collections import Counter

def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    bg = Counter(g.ravel()).most_common(1)[0][0]
    line = None
    for i in range(H):
        if np.all(g[i] == g[i, 0]) and g[i, 0] != bg:
            line = ('h', i, g[i, 0])
    for j in range(W):
        if np.all(g[:, j] == g[0, j]) and g[0, j] != bg:
            line = ('v', j, g[0, j])
    kind, pos, col = line
    out = np.full_like(g, bg)
    if kind == 'h':
        rows = [i for i in range(H) if i != pos and np.any(g[i] != bg)]
        o1, o2 = rows[0], rows[-1]
        cmin = min(np.where(g[r] != bg)[0].min() for r in rows)
        cmax = max(np.where(g[r] != bg)[0].max() for r in rows)
        oc = g[o1, cmin]
        if o1 < pos:
            n2 = pos - 1; n1 = n2 - (o2 - o1); far = n1 - 1
        else:
            n1 = pos + 1; n2 = n1 + (o2 - o1); far = n2 + 1
        out[pos, :] = col
        for r in rows:
            for c in range(cmin, cmax + 1):
                if g[r, c] != bg:
                    out[n1 + (r - o1), c] = g[r, c]
        out[far, :] = 8
    else:
        cols = [j for j in range(W) if j != pos and np.any(g[:, j] != bg)]
        c1, c2 = cols[0], cols[-1]
        rmin = min(np.where(g[:, c] != bg)[0].min() for c in cols)
        rmax = max(np.where(g[:, c] != bg)[0].max() for c in cols)
        oc = g[rmin, c1]
        if c1 < pos:
            n2 = pos - 1; n1 = n2 - (c2 - c1); far = n1 - 1
        else:
            n1 = pos + 1; n2 = n1 + (c2 - c1); far = n2 + 1
        out[:, pos] = col
        for c in cols:
            for r in range(rmin, rmax + 1):
                if g[r, c] != bg:
                    out[r, n1 + (c - c1)] = g[r, c]
        out[:, far] = 8
    return out.tolist()
'''
